	}
	url = gf_dm_sess_get_resource_name(sess->http_sess);
	if (!url) e = GF_BAD_PARAM;
	if (url[0]!='/') e = GF_BAD_PARAM;

	sess->do_log = httpout_do_log(sess, parameter->reply);

