	}
	gf_dynstrcat(&rsp_buf, "Server: ", NULL);
	gf_dynstrcat(&rsp_buf, sess->ctx->user_agent, NULL);
	gf_dynstrcat(&rsp_buf, "\r\n", NULL);
	httpout_insert_date(gf_net_get_utc(), &rsp_buf);

	if (sess->ctx->close) {
