			GF_LOG(GF_LOG_ERROR, GF_LOG_NETWORK, ("[HTTPOut] Cannot process PIDs width progressive download disabled\n"));
			return GF_BAD_PARAM;
		}

		GF_SAFEALLOC(pctx, GF_HTTPOutInput);
		pctx->ipid = pid;

		p = gf_filter_pid_get_property(pid, GF_PROP_PID_DASH_MODE);
